INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Haben Betroffene immer das Recht auf Auskunft über ihre Daten?', 2, '[{"text": "Ja", "correct": true, "because": "Grundrecht laut DSGVO"}, {"text": "Nein", "correct": false, "because": "Ausnahmen sind selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht erlaubt es Nutzern, falsche Daten korrigieren zu lassen?', 3, '[{"text": "Berichtigung", "correct": true, "because": "Korrigiert unrichtige Daten"}, {"text": "Löschung", "correct": false, "because": "Entfernt Daten, korrigiert nicht"}, {"text": "Auskunft", "correct": false, "because": "Zeigt Daten, ändert sie nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte haben Betroffene gemäß DSGVO?', 5, '[{"text": "Löschung", "correct": true, "because": "Recht auf Vergessenwerden"}, {"text": "Datenportabilität", "correct": true, "because": "Ermöglicht Datenübertragung"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Kein Betroffenenrecht"}, {"text": "Maximale Erhebung", "correct": false, "because": "Widerspricht Minimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Betroffene können Datenlöschung verlangen. b) Auskunft ist nur für große Firmen möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auskunft gilt für alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Umsetzung von Betroffenenrechten?', 4, '[{"text": "Anfragen der Nutzer", "correct": false, "because": "Müssen bearbeitet werden"}, {"text": "Fristen für Antworten", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Farbschema der Website", "correct": true, "because": "Nicht datenschutzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Recht auf Löschung absolut ist?', 2, '[{"text": "Nein", "correct": true, "because": "Ausnahmen wie gesetzliche Pflichten"}, {"text": "Ja", "correct": false, "because": "Beschränkungen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht erlaubt Nutzern, ihre Daten mitzunehmen?', 3, '[{"text": "Datenportabilität", "correct": true, "because": "Ermöglicht Übertragung"}, {"text": "Auskunft", "correct": false, "because": "Nur Information, kein Transfer"}, {"text": "Widerspruch", "correct": false, "because": "Stoppt Verarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen bei Betroffenenrechten?', 5, '[{"text": "Auskunft erteilen", "correct": true, "because": "Pflicht bei Anfrage"}, {"text": "Daten korrigieren", "correct": true, "because": "Bei Unrichtigkeit nötig"}, {"text": "Daten unbegrenzt speichern", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Betroffene können Widerspruch einlegen. b) Löschung gilt nur für sensible Daten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Löschung gilt für alle Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Betroffenenrechte zu gewährleisten?', 4, '[{"text": "Prozesse für Anfragen", "correct": false, "because": "Erforderlich für Umsetzung"}, {"text": "Dokumentation", "correct": false, "because": "Nachweis ist Pflicht"}, {"text": "Maximale Datensammlung", "correct": true, "because": "Widerspricht Rechten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Recht auf Auskunft kostenpflichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Grundsätzlich kostenlos"}, {"text": "Ja", "correct": false, "because": "Nur bei Missbrauch Gebühren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte unterstützen die Kontrolle über Daten?', 4, '[{"text": "Widerspruch", "correct": true, "because": "Stoppt Verarbeitung"}, {"text": "Berichtigung", "correct": true, "because": "Korrigiert Fehler"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Kein Nutzerrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Betroffene keine Rechte bei gesetzlicher Pflicht haben. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Rechte gelten mit Einschränkungen"}, {"text": "Ja", "correct": false, "because": "Rechte bleiben bestehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Umsetzung des Rechts auf Löschung?', 3, '[{"text": "Schnelle Reaktion", "correct": true, "because": "Fristen sind gesetzlich"}, {"text": "Maximale Speicherung", "correct": false, "because": "Widerspricht Recht"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenportabilität hilft beim Anbieterwechsel. b) Berichtigung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Berichtigung ist Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte stärken die Autonomie der Betroffenen?', 5, '[{"text": "Auskunft", "correct": true, "because": "Gibt Einsicht in Daten"}, {"text": "Widerspruch", "correct": true, "because": "Ermöglicht Kontrolle"}, {"text": "Hohe Verfügbarkeit", "correct": false, "because": "Kein Betroffenenrecht"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Kein Nutzerrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auskunft unwichtig?', 3, '[{"text": "Dateninhalt", "correct": false, "because": "Kern der Auskunft"}, {"text": "Verarbeitungszweck", "correct": false, "because": "Muss angegeben werden"}, {"text": "UI-Design", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit dem Widerspruchsrecht? Gilt es immer?', 3, '[{"text": "Nein", "correct": true, "because": "Eingeschränkt bei gesetzlicher Pflicht"}, {"text": "Ja", "correct": false, "because": "Ausnahmen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Betroffene Datenportabilität für alle Daten haben?', 2, '[{"text": "Nein", "correct": true, "because": "Nur für bereitgestellte Daten"}, {"text": "Ja", "correct": false, "because": "Beschränkungen gelten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht wähle ich, um Daten korrigieren zu lassen?', 4, '[{"text": "Berichtigung", "correct": true, "because": "Korrigiert unrichtige Daten"}, {"text": "Löschung", "correct": false, "because": "Entfernt, korrigiert nicht"}, {"text": "Auskunft", "correct": false, "because": "Zeigt Daten, ändert nichts"}]');
